#!/usr/bin/env bash
# Question 1: Deployment ${Q1_APP} not running. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
  labels: { app: ${Q1_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 100m, memory: 64Mi }
EOF
kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"

case "${Q1_FAULT}" in
  quota-pods)
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"ResourceQuota","metadata":{"name":"pod-quota"},"spec":{"hard":{"pods":"1"}}}'
    ;;
  quota-limits)
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"ResourceQuota","metadata":{"name":"compute-quota"},"spec":{"hard":{"requests.cpu":"2","limits.cpu":"4"}}}'
    ;;
  limitrange-max)
    kubectl -n "${Q1_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"LimitRange","metadata":{"name":"container-limits"},"spec":{"limits":[{"type":"Container","max":{"cpu":"50m"}}]}}'
    ;;
  node-affinity)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" -p '{"spec":{"template":{"spec":{"affinity":{"nodeAffinity":{"requiredDuringSchedulingIgnoredDuringExecution":{"nodeSelectorTerms":[{"matchExpressions":[{"key":"disktype","operator":"In","values":["ssd"]}]}]}}}}}}}'
    ;;
  priority-class)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" -p '{"spec":{"template":{"spec":{"priorityClassName":"critical-batch"}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q1_NS}" scale "deployment/${Q1_APP}" --replicas=2
sleep 15
[[ "$(kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q1_APP} still runs 2 replicas" >&2; exit 1; }
